package ru.neverland.townyarmy.tactics;

import java.util.*;
import ru.neverland.townyarmy.ArmyModel;

/** Additional military roles and frozen, individually receipted equipment. No Bukkit objects are persisted. */
public final class TacticsBook {
 private TacticsBook(){}
 public static final int MAX_PROFILES=20000,MAX_ORDERS=10000,MAX_KITS=20000,MAX_HISTORY=30000;
 public static final long DAY=86400000L;
 public enum Role { SOLDIER("Боец","IRON_SWORD"),SAPPER("Сапёр","TNT"),MEDIC("Медик","SPLASH_POTION"),SUPPLIER("Снабженец","BARREL");
  private final String title,icon;Role(String title,String icon){this.title=title;this.icon=icon;}public String title(){return title;}public String icon(){return icon;}public String id(){return name().toLowerCase(Locale.ROOT);}public static Role parse(String s){return valueOf(s.toUpperCase(Locale.ROOT));}
 }
 public enum Task { RALLY("Сбор"),ATTACK("Атака"),DEFEND("Оборона"),SUPPLY("Подвоз снабжения");private final String title;Task(String title){this.title=title;}public String title(){return title;}public String id(){return name().toLowerCase(Locale.ROOT);}}
 public enum OrderPhase { OPEN,COMPLETED,CANCELLED,EXPIRED }
 public enum KitPhase { PLANNED,FUNDED,ARMED,REVIEW,COMPLETE,CANCEL_PENDING,CANCELLED }
 public record Profile(UUID town,UUID player,Role role,UUID actor,long at){public Profile{ids(town,player,actor);Objects.requireNonNull(role);time(at);}public String key(){return town+"/"+player;}}
 public record Point(UUID world,double x,double y,double z){public Point{ids(world);if(!Double.isFinite(x)||!Double.isFinite(y)||!Double.isFinite(z)||Math.abs(x)>30000000||Math.abs(z)>30000000||Math.abs(y)>10000)throw new IllegalArgumentException("Недопустимая точка приказа");}public boolean contains(UUID w,double px,double py,double pz,double radius){return world.equals(w)&&Double.isFinite(radius)&&radius>0&&(x-px)*(x-px)+(y-py)*(y-py)+(z-pz)*(z-pz)<=radius*radius;}}
 public record Order(UUID id,UUID town,UUID actor,Task task,String unit,Point point,double radius,String description,long created,long expires,OrderPhase phase,Set<UUID> accepted,Set<UUID> arrived,long revision){
  public Order{ids(id,town,actor);Objects.requireNonNull(task);Objects.requireNonNull(point);Objects.requireNonNull(phase);text(description,160);time(created);if(!Double.isFinite(radius)||radius<2||radius>64||expires<=created||expires-created>DAY||revision<1||!Set.of("all","infantry","cavalry","navy","air").contains(unit))throw new IllegalArgumentException("Неверные условия приказа");accepted=Set.copyOf(accepted);arrived=Set.copyOf(arrived);if(accepted.size()>1000||!accepted.containsAll(arrived))throw new IllegalArgumentException("Неверное подтверждение приказа");}
  public Order mark(UUID player,boolean arrival,long now){if(phase!=OrderPhase.OPEN||now>=expires)throw new IllegalArgumentException("Приказ закрыт или его срок истёк");if(arrival?arrived.contains(player):accepted.contains(player))throw new IllegalArgumentException("Вы уже отметились в этом приказе");var a=new HashSet<>(accepted);var b=new HashSet<>(arrived);a.add(player);if(arrival)b.add(player);return new Order(id,town,actor,task,unit,point,radius,description,created,expires,phase,a,b,revision+1);}
  public Order close(OrderPhase next){if(phase!=OrderPhase.OPEN||next==OrderPhase.OPEN)throw new IllegalArgumentException("Приказ уже закрыт");return new Order(id,town,actor,task,unit,point,radius,description,created,expires,next,accepted,arrived,revision+1);}
 }
 public record Kit(UUID id,UUID town,UUID player,Role role,Map<String,Long> cost,List<String> items,long created,long cooldown,int perDay,KitPhase phase,long phaseAt,String reason){
  public Kit{ids(id,town,player);Objects.requireNonNull(role);Objects.requireNonNull(phase);cost=ArmyModel.stock(cost);items=List.copyOf(items);time(created);text(reason,200);if(cost.isEmpty()||items.isEmpty()||items.size()>16||items.stream().anyMatch(s->s==null||s.isBlank()||s.length()>32768)||cooldown<60000||cooldown>DAY||perDay<1||perDay>10||phaseAt<created)throw new IllegalArgumentException("Неверная квитанция военного комплекта");}
  public boolean terminal(){return phase==KitPhase.COMPLETE||phase==KitPhase.CANCELLED;}
  public Kit phase(KitPhase next,String note,long now){boolean allowed=switch(phase){case PLANNED->next==KitPhase.FUNDED||next==KitPhase.CANCEL_PENDING;case FUNDED->next==KitPhase.ARMED||next==KitPhase.CANCEL_PENDING;case ARMED->next==KitPhase.COMPLETE||next==KitPhase.REVIEW||next==KitPhase.CANCEL_PENDING;case REVIEW->next==KitPhase.COMPLETE||next==KitPhase.CANCEL_PENDING;case CANCEL_PENDING->next==KitPhase.CANCELLED;default->false;};if(!allowed)throw new IllegalArgumentException("Недопустимый переход выдачи комплекта");return new Kit(id,town,player,role,cost,items,created,cooldown,perDay,next,Math.max(now,phaseAt+1),note);}
 }
 public record Entry(UUID id,UUID operation,UUID town,UUID actor,UUID subject,String action,String reason,long at,boolean audited){public Entry{ids(id,operation,town,actor,subject);text(action,40);text(reason,300);time(at);}public Entry(UUID id,UUID town,UUID actor,UUID subject,String action,String reason,long at,boolean audited){this(id,id,town,actor,subject,action,reason,at,audited);}public Entry ack(){return new Entry(id,operation,town,actor,subject,action,reason,at,true);}public Entry operation(UUID op){return new Entry(id,op,town,actor,subject,action,reason,at,audited);}}
 public record State(Map<String,Profile> profiles,Map<UUID,Order> orders,Map<UUID,Kit> kits,List<Entry> history,long revision){
  public State{profiles=Map.copyOf(profiles);orders=Map.copyOf(orders);kits=Map.copyOf(kits);history=List.copyOf(history);if(profiles.size()>MAX_PROFILES||orders.size()>MAX_ORDERS||kits.size()>MAX_KITS||history.size()>MAX_HISTORY||revision<0)throw new IllegalArgumentException("Военный журнал достиг предела");profiles.forEach((k,p)->{if(!k.equals(p.key()))throw new IllegalArgumentException("Профиль другого бойца");});orders.forEach((k,o)->{if(!k.equals(o.id()))throw new IllegalArgumentException("Приказ с другим ID");});kits.forEach((k,o)->{if(!k.equals(o.id()))throw new IllegalArgumentException("Комплект с другим ID");});var blocked=new HashSet<UUID>();for(var kit:kits.values())if(!kit.terminal()&&!blocked.add(kit.player()))throw new IllegalArgumentException("У бойца уже есть незавершённая выдача");var ids=new HashSet<UUID>();long at=0;for(var e:history){if(!ids.add(e.id())||e.at()<at)throw new IllegalArgumentException("Нарушена последовательность военного журнала");at=e.at();}}
  public static State empty(){return new State(Map.of(),Map.of(),Map.of(),List.of(),0);}
  public Role role(UUID town,UUID player){var p=profiles.get(town+"/"+player);return p==null?Role.SOLDIER:p.role();}
  public Optional<Kit> pending(UUID player){return kits.values().stream().filter(k->k.player().equals(player)&&!k.terminal()).findFirst();}
  private State image(Map<String,Profile> p,Map<UUID,Order> o,Map<UUID,Kit> k,Entry entry){var h=new ArrayList<>(history);long at=h.isEmpty()?entry.at():Math.max(entry.at(),h.get(h.size()-1).at()+1);h.add(new Entry(entry.id(),entry.operation(),entry.town(),entry.actor(),entry.subject(),entry.action(),entry.reason(),at,false));return new State(p,o,k,h,Math.addExact(revision,1));}
  public State role(Profile p,Entry e){var m=new HashMap<>(profiles);m.put(p.key(),p);return image(m,orders,kits,e);}
  public State order(Order order,long expected,Entry e){var old=orders.get(order.id());if(old==null?expected!=0||order.revision()!=1||order.phase()!=OrderPhase.OPEN:old.revision()!=expected)throw new IllegalArgumentException("Приказ изменился: откройте его заново");if(old!=null&&(!old.town().equals(order.town())||!old.actor().equals(order.actor())||!old.point().equals(order.point())||old.radius()!=order.radius()||old.task()!=order.task()||!old.unit().equals(order.unit())||!old.description().equals(order.description())||old.created()!=order.created()||old.expires()!=order.expires()||old.phase()!=OrderPhase.OPEN||!order.accepted().containsAll(old.accepted())||!order.arrived().containsAll(old.arrived())||old.revision()+1!=order.revision()))throw new IllegalArgumentException("Неверное изменение приказа");var m=new HashMap<>(orders);m.put(order.id(),order);return image(profiles,m,kits,e.operation(order.id()));}
  public State plan(Kit kit,Entry entry){if(kit.phase()!=KitPhase.PLANNED||kits.containsKey(kit.id())||pending(kit.player()).isPresent())throw new IllegalArgumentException("Предыдущий комплект ещё обрабатывается");long count=kits.values().stream().filter(k->k.player().equals(kit.player())&&k.phase()!=KitPhase.CANCELLED&&k.created()>kit.created()-DAY).count();long last=kits.values().stream().filter(k->k.player().equals(kit.player())&&k.phase()!=KitPhase.CANCELLED).mapToLong(Kit::created).max().orElse(0);if(count>=kit.perDay()||last>0&&last>kit.created()-kit.cooldown())throw new IllegalArgumentException("Новый комплект пока недоступен: действует перерыв или предел за 24 часа");var m=new HashMap<>(kits);m.put(kit.id(),kit);return image(profiles,orders,m,entry.operation(kit.id()));}
  public State kit(UUID id,KitPhase next,String reason,long now,UUID actor){var old=Objects.requireNonNull(kits.get(id),"Комплект не найден");var m=new HashMap<>(kits);m.put(id,old.phase(next,reason,now));return image(profiles,orders,m,new Entry(UUID.randomUUID(),id,old.town(),actor,old.player(),"ARMY_KIT_"+next.name(),reason,now,false));}
  public State acknowledge(Set<UUID> ids){if(ids.size()>64)throw new IllegalArgumentException("Слишком большая пачка журнала");return new State(profiles,orders,kits,history.stream().map(e->ids.contains(e.id())?e.ack():e).toList(),revision);}
 }
 static void ids(UUID...ids){for(UUID id:ids)Objects.requireNonNull(id);}
 static void time(long at){if(at<0)throw new IllegalArgumentException("Неверное время");}
 static void text(String value,int max){if(value==null||value.isBlank()||value.length()>max||value.chars().anyMatch(c->Character.isISOControl(c)||c=='§'||c=='&'))throw new IllegalArgumentException("Некорректное описание");}
}
